  if (!m) throw new RangeError(`bad amount: ${text}`);
  const den = Number(m[3]);
  if (den === 0) throw new RangeError(`zero denominator: ${text}`);
  return (m[1] ? Number(m[1]) : 0) + Number(m[2]) / den;
}

function gcd(a, b) {
  return b === 0 ? a : gcd(b, a % b);
}

