  if (!Object.hasOwn(TSP, unit)) return { amount, unit };
  const t = amount * TSP[unit];
  if (t >= 48) return { amount: t / 48, unit: 'cup' };
  if (t >= 3) return { amount: t / 3, unit: 'tbsp' };
  return { amount: t, unit: 'tsp' };
